"""FM-16K editorial six-tier pathways. Original questions, teacher pending."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,t,x,y,z,C=s.symbols('k h t x y z C',real=True)
PATHS={'fixed-invariant':'MAT.invariants.distinguish','nonunique-set':'MAT.systems.nonunique','plane-common-point':'VEC.plane-intersection.point','related-solids':'VEC.area-volume.related-solids'}
RATIONALES={
'fixed-invariant':['Recall substitution in a line equation.','Distinguish pointwise fixation from setwise invariance.','Find the image of a given line and test both properties.','Link coordinate mapping and geometric conditions to classify several lines.','Recover a parameter from invariance and then determine fixed points.','Classify every affine invariant line including singular and identity cases.'],
'nonunique-set':['Recall solving a single equation.','Diagnose why redundant equations leave a free variable.','Parameterise a consistent dependent system.','Convert a parametric solution to geometric form and impose a further constraint.','Recover a free parameter from a geometric distance condition, retaining both signs.','Classify all nonnegative solutions of a system and prove feasibility boundaries.'],
'plane-common-point':['Check coordinates in a plane.','Diagnose why one plane equation does not ensure common membership.','Find a common point by fixing a coordinate and solving.','Find two distinct common points and verify their line.','Find a common point subject to an additional geometric constraint.','Minimise distance from the origin over all common points using an exact proof.'],
'related-solids':['Recall base-area times height.','Explain the geometric factor between prism and tetrahedron.','Calculate tetrahedron volume from three displacement vectors.','Compare related solids and recover a perpendicular height.','Recover a cut parameter from a prescribed volume ratio.','Classify attainable tetrahedron volume ratios under two linked edge constraints.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;c=2*v+3
 if path=='fixed-invariant':
  A=M([[1,0],[0,a]])
  if l==1:
   q=f'Determine whether the point ({b},{a*b}) lies on y={a}x by substitution.';f=[True];ans='Yes.';steps=[f'Substituting x={b} gives y={a*b}, as required.'];hints=['Substitute the x coordinate.','Compare with the given y coordinate.'];mistake='Checking the x coordinate alone.'
  elif l==2:
   q=f'Under A={L(A)}, a learner says the y-axis is fixed pointwise because its image is the y-axis. Explain the error, and give the image of (0,{b}).';f=[M([0,a*b])];ans=f'The y-axis is invariant but not fixed pointwise; the image is (0,{a*b}).';steps=['All points on the y-axis remain on it, and since the scale is nonzero its image is the whole axis.',f'The point (0,{b}) maps to (0,{a*b}), which differs because the scale is not 1.'];hints=['Distinguish the set from its individual points.','Test a nonzero point.'];mistake='Equating invariant with fixed pointwise.'
  elif l==3:
   q=f'Find the image equation of x={c} under A={L(A)}. Decide if this line is invariant and if it is fixed pointwise.';f=[c,True,False];ans=f'X={c}; invariant, not fixed pointwise.';steps=[f'A general point ({c},t) maps to ({c},{a}t).',f'As t ranges over the reals, so does {a}t, hence the whole line is its image.',f'At t=1 the y coordinate changes from 1 to {a}, so the line is not fixed pointwise.'];hints=['Parameterise the line.','Check whether every image point equals its preimage.'];mistake='Testing only the point on the x-axis.'
  elif l==4:
   q=f'Under A={L(A)}, classify the lines y=0, y={b}, and x={c} as pointwise fixed, invariant but not pointwise fixed, or not invariant. Derive their image equations.';f=[0,a*b,c];ans=f'y=0 fixed pointwise; y={b} not invariant (image Y={a*b}); x={c} invariant but not fixed pointwise.';steps=[f'(x,0) stays (x,0), so the x-axis is pointwise fixed.',f'(x,{b}) maps to (x,{a*b}), giving a different horizontal line.',f'({c},t) maps to ({c},{a}t); this covers the same vertical line but moves nonzero y coordinates.'];hints=['Map a general point on each line.','Check set equality before pointwise equality.'];mistake='Assuming every horizontal line is fixed because x is unchanged.'
  elif l==5:
   A=M([[1,k],[0,a]]);m=s.Rational(a-1,b);q=f'The line y={L(m)}x is invariant under A={L(A)}. Find k and determine all fixed points on that line. Justify uniqueness.';f=[b,M([0,0])];ans=f'k={b}; only the origin on the line is fixed.';steps=[f'Its direction (1,{L(m)}) maps to (1+k m,{L(a*m)}).',f'For invariance the image must be a nonzero multiple of the direction. Since m is nonzero, the multiple must be {a}, so 1+k m={a}.',f'Solving gives k={b}, uniquely. The multiple {a} is not 1, so only the zero vector on this line is fixed.'];hints=['Compare the two direction components.','An invariant direction can be scaled without being fixed.'];mistake='Requiring the direction multiplier to be 1.'
  else:
   A=M([[1,0],[0,k/v]]);q=f'For every real k classify all affine lines invariant as sets under A={L(A)}. For each case identify all pointwise fixed lines. Prove the classification is exhaustive.';f=[k/v,0,v];ans=f'k={v}: every line fixed pointwise. k=0: only y=0 invariant, fixed pointwise. k nonzero and not {v}: all x=d (d real) and y=0 invariant; only y=0 fixed pointwise.';steps=[f'If k={v} the map is the identity. If k=0, the entire image lies on y=0, so any invariant line must be that line, which is indeed fixed.', f'For k nonzero and not {v}, a vertical line x=d maps onto itself because Y=({L(k/v)})y ranges over all reals; it is not fixed pointwise.', f'A nonvertical line y=m x+d maps to Y=({L(k/v)})m X+({L(k/v)})d. Equality of lines requires (k-{v})m=(k-{v})d=0, hence m=d=0.', 'The x-axis is pointwise fixed. Every affine line is vertical or nonvertical, so these cases exhaust all possibilities.'];hints=['Separate k=0 and k=1 before cancellation.','Use vertical and nonvertical representations.'];mistake='Treating the point image of a vertical line at k=0 as an invariant line.'
 elif path=='nonunique-set':
  if l==1:
   q=f'Given x+y={b} and y={a}, find x.';f=[b-a];ans=str(b-a);steps=[f'Subtract y={a} from {b} to obtain x={b-a}.'];hints=['Substitute y.','Rearrange the sum.'];mistake='Adding the specified y value.'
  elif l==2:
   q=f'A student claims x+y={b}, {a}x+{a}y={a*b} has a unique solution because there are two equations. Explain the error and give two different solutions.';f=[M([b,0]),M([0,b])];ans=f'The equations are dependent; ({b},0) and (0,{b}) are distinct solutions.';steps=[f'The second equation is {a} times the first, so it introduces no independent restriction.',f'Both ({b},0) and (0,{b}) satisfy the same sum. Therefore uniqueness is impossible.'];hints=['Compare both left and right sides.','Try setting one variable to zero.'];mistake='Counting equations instead of independent conditions.'
  elif l==3:
   q=f'Find the complete solution set of x+y+z={b}, y+{a}z={c}. Use z=t as the free parameter.';f=[M([b-c+(a-1)*t,c-a*t,t])];ans=L(f[0])+', t real.';steps=[f'Let z=t; the second equation gives y={L(c-a*t)}.',f'Substitution into the first gives x={L(b-c+(a-1)*t)}. Every t is permitted and every solution has a value of z.'];hints=['Choose z freely.','Solve the two remaining equations in order.'];mistake='Setting the free parameter to zero and reporting only one solution.'
  elif l==4:
   q=f'Express all solutions of x+y={b}, y+z={c}, x-z={b-c} as a vector line. Find the point on that line with z={a}.';f=[M([b-c,c,0]),M([1,-1,1]),M([b-c+a,c-a,a])];ans=f'r={L(f[0])}+t{L(f[1])}; point {L(f[2])}.';steps=['The third equation follows by subtracting the second from the first, so it is redundant.',f'Let z=t, then y={L(c-t)} and x={L(b-c+t)}. This gives the stated vector line.',f'Setting t={a} gives {L(f[2])}, which satisfies all three original equations.'];hints=['Identify the redundant equation.','Separate the constant point from the free direction.'];mistake='Treating the dependent third equation as a new restriction.'
  elif l==5:
   P=M([b,c,0]);D=M([1,-1,1]);target=a*a*3;q=f'The system x+y={b+c}, y+z={c}, x-z={b} has infinitely many solutions. Find all its solutions at distance {L(s.sqrt(target))} from P={L(P)}. Prove completeness.';f=[P-a*D,P+a*D];ans=' or '.join(L(i) for i in f);steps=[f'Taking z=t gives the whole solution line P+t{L(D)}.',f'The squared distance from P is 3t^2. Equating to {target} gives t=±{a}.','Both signs yield points on the solution line at the prescribed distance; no other t solves the squared equation.'];hints=['Parameterise using z.','Distance depends on the magnitude of the free parameter.'];mistake='Discarding the negative parameter.'
  else:
   q=f'For every real h classify all nonnegative real solutions of x+y+z={b}, y+{a}z=h. Give the complete parameter interval, classify zero, one or infinitely many solutions, and prove the endpoints.';f=[0,a*b,h/a,(h-b)/(a-1)];ans=f'No solution outside 0≤h≤{a*b}. For 0≤h≤{a*b}, (x,y,z)=({b}-h+({a}-1)t,h-{a}t,t), max(0,(h-{b})/({a}-1))≤t≤h/{a}. Exactly one solution at h=0 or h={a*b}, infinitely many otherwise.';steps=[f'Let z=t; then y=h-{a}t and x={b}-h+({a}-1)t.',f'Nonnegativity is equivalent to t≥0, t≤h/{a}, and t≥(h-{b})/({a}-1).',f'If h<0 then the upper bound is negative. If h>{a*b}, the lower bound (h-{b})/({a}-1) exceeds h/{a}. Conversely for 0≤h≤{a*b} both lower bounds are at most the upper bound.',f'At h=0 the interval is the singleton t=0; at h={a*b} it is the singleton t={b}. Strictly between the endpoints the interval has positive length, giving infinitely many solutions.', 'The parameterisation and inequalities were equivalent to the original constraints, so all solutions are included.'];hints=['Use z as the free variable.','Translate each nonnegativity condition into an interval bound.'];mistake='Assuming a free parameter can take every real value even with nonnegativity constraints.'
 elif path=='plane-common-point':
  if l==1:
   q=f'Check whether ({a},{b},{c}) lies on x+y+z={a+b+c}.';f=[a+b+c];ans='Yes.';steps=[f'The coordinate sum is {a+b+c}, the plane constant.'];hints=['Add the three coordinates.','Compare the sum to the right-hand side.'];mistake='Checking just one coordinate.'
  elif l==2:
   q=f'A learner says P=({a},{b},0) lies on both x+y={a+b} and x+z={a+1}. Explain the error.';f=[a+b,a];ans='P lies on the first plane only.';steps=[f'x+y={a+b}, so P is on the first plane.',f'x+z={a}, not {a+1}; membership of one plane does not establish common membership.'];hints=['Substitute into both equations.','The same coordinates must satisfy both.'];mistake='Checking only one plane.'
  elif l==3:
   q=f'Find a common point of x+y={b}, x+{a}y+z={c} with y=0.';f=[M([b,0,c-b])];ans=L(f[0]);steps=[f'With y=0 the first equation gives x={b}.',f'The second gives z={c-b}. Substitution checks both equations.'];hints=['Fix the specified coordinate first.','Use the first plane to solve for x.'];mistake='Solving each plane separately with different points.'
  elif l==4:
   P=M([b,0,c-b]);Q=M([b-1,1,c-b-(a-1)]);D=Q-P;q=f'Find common points of x+y={b}, x+{a}y+z={c} with y=0 and y=1 respectively. Use them to give and verify the entire intersection line.';f=[P,Q,D];ans=f'r={L(P)}+t{L(D)}, t real.';steps=[f'For y=0, x={b}, z={c-b}; for y=1, x={b-1}, z={c-b-(a-1)}.',f'The two distinct common points yield direction {L(D)}.',f'Every point on the stated line has x+y={b} and x+{a}y+z={c}. Conversely each common point is determined by its y coordinate, so the line is complete.'];hints=['Use each specified y separately.','Check both plane equations along the line.'];mistake='Using the sum rather than difference of the common points as direction.'
  elif l==5:
   # impose x=z; x=b-y, z=c-b-(a-1)y, choose a >= 3 instead to avoid coincidence
   d=a+1;Y=s.Rational(c-2*b,d-2);P=M([b-Y,Y,b-Y]);q=f'Find the common point of x+y={b}, x+{d}y+z={c} lying on the plane x=z. Prove uniqueness.';f=[P];ans=L(P);steps=[f'With x=z, the second equation becomes 2x+{d}y={c}.',f'Eliminating x using x+y={b} gives {d-2}y={c-2*b}. The coefficient is nonzero, so y={L(Y)} uniquely.',f'Substitute to obtain {L(P)}; the three equations hold.'];hints=['Use x=z to reduce the number of variables.','Eliminate x using the first plane.'];mistake='Assuming any common point of the first two planes meets the third.'
  else:
   P=M([b,0,h-b]);D=M([-1,1,1-k]);T=s.factor(-P.dot(D)/D.dot(D));Q=s.simplify(P+T*D);dist=s.factor(Q.dot(Q));q=f'For all real k,h, find the common point of x+y={b}, x+ky+z=h nearest the origin. Give its coordinates and squared distance, and prove it is unique.';f=[T,Q,dist];ans=f'y={L(T)}; point {L(Q)}; squared distance {L(dist)}.';steps=[f'Set y=t. All common points are r={L(P)}+t{L(D)}.',f'The squared distance is (r dot r), a quadratic with leading coefficient {L(D.dot(D))}, strictly positive for all real k.',f'Completing the square yields its unique minimiser t=-(P dot D)/(D dot D)={L(T)}.',f'Substitute to obtain {L(Q)}, with squared distance {L(dist)}. The positive coefficient proves global minimality and uniqueness.'];hints=['Write a common point using y as parameter.','Minimise squared distance, not the signed coordinates.'];mistake='Choosing y=0 without checking whether it minimises distance.'
 elif path=='related-solids':
  U=M([a,0,0]);V=M([1,b,0]);W=M([1,2,c]);D=a*b*c
  if l==1:
   q=f'A prism has base area {a*b} and perpendicular height {c}. Find its volume.';f=[D];ans=str(D);steps=[f'Volume = base area × perpendicular height = {D}.'];hints=['Use the prism volume formula.','Multiply the supplied dimensions.'];mistake='Applying the tetrahedron factor to a prism.'
  elif l==2:
   q=f'A triangular prism and tetrahedron have the same triangular base and perpendicular height. The prism volume is {3*D}. Explain the relationship and find the tetrahedron volume.';f=[D];ans=str(D);steps=['The prism has constant cross-sectional area. The tetrahedron has pyramid volume equal to one third of base area times height.',f'Thus its volume is {3*D}/3={D}.'];hints=['Use the pyramid volume formula.','The factor compares the same triangular base and height.'];mistake='Using one sixth of the triangular prism volume instead of one third.'
  elif l==3:
   q=f'Find the volume of the tetrahedron with three edges from the same vertex {L(U)}, {L(V)}, {L(W)}.';f=[s.Rational(D,6)];ans=L(f[0]);steps=[f'The scalar triple product is {D}.',f'The tetrahedron occupies one sixth of the parallelepiped volume, so its volume is {L(f[0])}.'];hints=['Calculate the scalar triple product.','Use the absolute value and tetrahedron factor.'];mistake='Using the full parallelepiped volume.'
  elif l==4:
   q=f'A tetrahedron has adjacent edges {L(U)}, {L(V)}, {L(W)}. Find its volume, the volume of a prism with the same triangular base and perpendicular height, and recover that height from the prism volume and base area.';f=[s.Rational(D,6),s.Rational(D,2),c];ans=f'Tetrahedron {L(f[0])}; prism {L(f[1])}; height {c}.';steps=[f'The triangular base area is {L(s.Rational(a*b,2))} from half the cross-product magnitude.',f'The tetrahedron volume is one sixth of the absolute triple product, {L(f[0])}.',f'The triangular prism volume is three times the tetrahedron volume, {L(f[1])}. Dividing by base area gives perpendicular height {c}.'];hints=['Distinguish triangular base from parallelogram base.','Use the prism-to-tetrahedron volume ratio.'];mistake='Using the parallelogram base area for the triangular prism.'
  elif l==5:
   r=s.Rational(v,v+2);q=f'In nondegenerate tetrahedron OABC, P lies on OA and Q lies on OB with OP/OA=OQ/OB=t, where 0≤t≤1. The volume of OPQC is {L(r*r)} times the volume of OABC. Find t and prove uniqueness.';f=[r];ans=L(r);steps=['The two changed edge vectors are each multiplied by t, so the scalar triple product and volume ratio are multiplied by t^2.',f'Equating gives t^2={L(r*r)}. Since t≥0, the unique admissible root is {L(r)}.'];hints=['Use multilinearity of the scalar triple product.','Check the allowed interval for the edge fraction.'];mistake='Treating the volume ratio as t instead of t squared.'
  else:
   r=s.Rational(v,v+1);f=[r/4,s.sqrt(1-4*C/r)];q=f'In nondegenerate tetrahedron OABC, P,Q,R lie on OA, OB, OC respectively with OP/OA=t, OQ/OB=1-t, OR/OC={L(r)}, 0≤t≤1. For any real prescribed volume ratio C=Vol(OPQR)/Vol(OABC), classify all possible t and prove the maximum ratio. Include zero-volume endpoint configurations.';ans=f'Maximum ratio {L(r/4)} at t=1/2. No t for C<0 or C>{L(r/4)}; two t at C=0 and for 0<C<{L(r/4)}; one t at the maximum. Roots t=(1±{L(f[1])})/2.';steps=[f'The scalar triple product scales by the product of the three nonnegative edge fractions, giving C={L(r*t*(1-t))}.',f'Completing the square gives C={L(r/4)}-{L(r)}(t-1/2)^2. Hence the maximum is {L(r/4)}, uniquely at t=1/2, and the ratio cannot be negative on [0,1].',f'Solving the quadratic gives t=(1±{L(f[1])})/2. When 0≤C≤{L(r/4)}, the radical is in [0,1], so both candidates are admissible.', 'At C=0 the two endpoint configurations are degenerate. At the maximum the roots coincide; strictly between, they are distinct. Outside the attainable interval there is no solution.'];hints=['Scale the three edge vectors in the volume formula.','Complete the square and enforce the edge-fraction interval.'];mistake='Allowing roots outside the edge segments or counting a repeated root twice.'
 else:raise ValueError(path)
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mistake,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
